<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { CheckCircle2, Database, ExternalLink, HardDrive, Moon, Save, Server, Sun, Zap } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import { api } from '../api'
import { useAppStore } from '../stores/app'

const store = useAppStore()
const apiEndpoint = ref(localStorage.getItem('json-diff-api-endpoint') || '/api')
const theme = ref<'light' | 'dark'>(store.darkMode ? 'dark' : 'light')
const autoHistory = ref(localStorage.getItem('json-diff-auto-history') !== 'false')
const maxHistory = ref(Number(localStorage.getItem('json-diff-max-history') || 200))
const saved = ref(false)
const recentCount = computed(() => store.recentHistory.length)

function saveSettings() {
  localStorage.setItem('json-diff-api-endpoint', apiEndpoint.value)
  localStorage.setItem('json-diff-auto-history', String(autoHistory.value))
  localStorage.setItem('json-diff-max-history', String(maxHistory.value))
  if ((theme.value === 'dark') !== store.darkMode) store.toggleDarkMode()
  saved.value = true
  window.setTimeout(() => { saved.value = false }, 1800)
  ElMessage.success('系统设置已保存')
}

function setTheme(value: 'light' | 'dark') { theme.value = value; if ((value === 'dark') !== store.darkMode) store.toggleDarkMode() }

onMounted(() => store.initialize())
</script>

<template>
  <div class="view settings-view">
    <div class="view-heading"><div><p class="eyebrow">RUNTIME / 06</p><h1>系统设置</h1><p>管理工作台连接、主题与本地历史策略。</p></div><div class="heading-actions"><el-button type="primary" :disabled="saved" @click="saveSettings"><CheckCircle2 v-if="saved" :size="15" /><Save v-else :size="15" />{{ saved ? '已保存' : '保存设置' }}</el-button></div></div>
    <div class="settings-layout"><section class="settings-main panel"><div class="settings-section"><div class="settings-section-head"><div><h3><Server :size="16" />服务连接</h3><p>前端请求会发送到下面的 API 地址。</p></div><span class="connection-pill"><i></i>已连接</span></div><div class="settings-field"><label>API 基础地址</label><el-input v-model="apiEndpoint" placeholder="/api"><template #prefix><ExternalLink :size="14" /></template></el-input><small>修改后会在下一次页面加载时生效</small></div></div><div class="settings-section"><div class="settings-section-head"><div><h3><Sun :size="16" />外观</h3><p>选择适合长时间审核工作的界面主题。</p></div></div><div class="theme-options"><button :class="{ active: theme === 'light' }" type="button" @click="setTheme('light')"><span class="theme-preview light-preview"><i></i><i></i><i></i></span><span><strong>亮色主题</strong><small>清晰、明亮</small></span><CheckCircle2 v-if="theme === 'light'" :size="16" /></button><button :class="{ active: theme === 'dark' }" type="button" @click="setTheme('dark')"><span class="theme-preview dark-preview"><i></i><i></i><i></i></span><span><strong><Moon :size="13" />深色主题</strong><small>低亮度、专注</small></span><CheckCircle2 v-if="theme === 'dark'" :size="16" /></button></div></div><div class="settings-section"><div class="settings-section-head"><div><h3><Database :size="16" />历史与数据</h3><p>控制本地历史记录的保留行为。</p></div></div><div class="settings-switch-row"><div><strong>自动保存比较历史</strong><small>每次比较完成后保留请求与差异快照</small></div><el-switch v-model="autoHistory" /></div><div class="settings-field small-field"><label>历史记录上限</label><el-input-number v-model="maxHistory" :min="20" :max="1000" :step="20" controls-position="right" size="small" /><small>服务端默认最多保留 200 条记录</small></div></div></section><aside class="settings-side"><div class="status-panel panel"><div class="status-panel-head"><Zap :size="16" class="title-icon" /><strong>运行状态</strong></div><div class="status-row"><span>API 服务</span><span class="status-ok"><i></i>正常</span></div><div class="status-row"><span>比较引擎</span><span class="status-ok"><i></i>在线</span></div><div class="status-row"><span>规则配置</span><strong>{{ store.profiles.length }} 套</strong></div><div class="status-row"><span>最近记录</span><strong>{{ recentCount }} 条</strong></div><div class="status-foot"><HardDrive :size="14" />数据目录：<code>backend/…/data</code></div></div><div class="about-panel panel"><span class="about-mark"><Zap :size="18" /></span><strong>Interface JSON Compare</strong><span>接口响应比较平台 · V1.0</span><small>ASP.NET Core 10 · Vue 3 · TypeScript</small></div></aside></div>
  </div>
